//! Payment prioritisation — where THIS month's spare money goes, and in what order.
//!
//! `payoff` already answers "what does the whole schedule look like at $X a month". This answers the
//! question that comes first and gets skipped: how much is genuinely spare, and is the highest rate
//! really the right target right now. Three rules, in order, and the middle one is the one people
//! get wrong:
//!
//! 1. **Minimums are not negotiable.** Nothing paid above a minimum is worth a minimum missed — that
//!    is a late fee, a penalty rate on the whole balance, and a credit event that outlasts the month.
//! 2. **A buffer beats the rate, until it exists.** Paying a card down to zero liquid and then
//!    meeting a car repair puts the repair back on the card at 25% WITH a fee, so the "optimal"
//!    payment lost money. Avalanche is optimal *given the balance stays paid*; a person with no
//!    buffer cannot make that promise, and arithmetic that ignores it is not conservative, it is
//!    wrong.
//! 3. **Then the rate — except a 0% promotional balance, which inverts.** While the promotion runs
//!    it costs nothing to carry and paying it is the worst use of a dollar; when it is about to END
//!    it becomes the most urgent thing on the list, because the whole balance is about to start
//!    accruing at once. Deprioritised, then jumped to the front, on a date.
//!
//! And if the runway does not hold, THERE IS NO SURPLUS. The honest answer is "pay the minimums and
//! nothing more", and it is an answer this module will actually give.
use crate::money::{money, Currency, Money};
use crate::payoff::Strategy;
use crate::position::{AccountPosition, Position};
use crate::runway::{survives_horizon, Runway};

pub(crate) use promo_end_for::promo_end_for;
pub use promo_state_of::promo_state_of;
pub(crate) use promo_rank::promo_rank;
pub use priority_order::priority_order;
pub(crate) use why_target::why_target;
pub use total_commitment::total_commitment;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AllocationKind {
    Minimum,
    Buffer,
    Extra,
}

impl AllocationKind {
    pub fn label(self) -> &'static str {
        match self {
            AllocationKind::Minimum => "minimum",
            AllocationKind::Buffer => "buffer",
            AllocationKind::Extra => "extra",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Allocation {
    pub kind: AllocationKind,
    /// Absent for the buffer, which is not paid to anybody.
    pub account: Option<String>,
    pub label: String,
    pub amount: Money,
    /// Why this, before the others.
    pub reason: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Target {
    pub account: String,
    pub institution: String,
    pub why: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Priority {
    pub currency: Currency,
    pub strategy: Strategy,
    /// What the runway says is genuinely spare EVERY month, not on a good one.
    pub available: Money,
    /// Liquid above the buffer target — a one-off, distinct from the monthly figure.
    pub lump_available: Money,
    pub minimums: Money,
    pub to_buffer: Money,
    pub to_debt: Money,
    pub allocations: Vec<Allocation>,
    /// The ONE account to put every spare dollar into. Absent when nothing spare exists.
    pub target: Option<Target>,
    /// The full order, so the answer AFTER this one is already visible.
    pub order: Vec<String>,
    pub warnings: Vec<String>,
}

pub struct PriorityOptions<'a> {
    /// Liquid to hold before any dollar goes above a minimum.
    pub buffer_target: Money,
    pub strategy: Strategy,
    /// `YYYY-MM-DD` a 0% promotional rate ends, per account.
    pub promo_ends: &'a [(String, String)],
    /// How close a promotion's end makes it URGENT rather than cheap.
    pub promo_urgency_days: i64,
    /// Utilisation above which a credit line is called out.
    pub utilisation_concern: f64,
}

impl<'a> PriorityOptions<'a> {
    pub fn new(buffer_target: Money) -> Self {
        PriorityOptions { buffer_target, strategy: Strategy::Avalanche, promo_ends: &[], promo_urgency_days: 90, utilisation_concern: 0.9 }
    }
}

/// A live 0% promotion makes a balance cost nothing to carry — until it does not.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PromoState {
    None,
    Live,
    Expiring,
}

pub fn prioritise(position: &Position, runway: &Runway, opts: &PriorityOptions) -> Priority {
    let currency = position.currency;
    let mut warnings: Vec<String> = Vec::new();

    let debts: Vec<AccountPosition> = position.accounts.iter().filter(|a| a.owed.is_some()).cloned().collect();
    let minimums: i64 = debts.iter().map(|a| a.minimum_payment.map(|m| m.minor).unwrap_or(0)).sum();

    // WHAT IS GENUINELY SPARE is the WORST month's net under the low band, not a good month's. A
    // monthly commitment made out of the best month is a commitment that fails in the worst one.
    let nets: Vec<i64> = runway.headline.months.iter().map(|m| m.net.minor).collect();
    let worst_net = nets.iter().min().copied().unwrap_or(0);
    let mut available = worst_net.max(0);

    if runway.headline.months.is_empty() {
        warnings.push("there is no runway to read a surplus from, so nothing above the minimums is recommended".to_string());
        available = 0;
    } else if !survives_horizon(&runway.headline) {
        // THE HONEST AND UNUSUAL ANSWER. Every dollar above a minimum makes the shortfall arrive
        // sooner, so the recommendation is to pay the minimums and nothing more.
        warnings.push(format!(
            "the money runs out in {} on the low income band — there is no surplus, and anything paid above the minimums brings that date forward",
            runway.headline.exhausts_in.clone().unwrap_or_default()
        ));
        available = 0;
    }

    let lump_available = (position.liquid.minor - opts.buffer_target.minor).max(0);
    let buffer_short = (opts.buffer_target.minor - position.liquid.minor).max(0);
    let to_buffer = available.min(buffer_short);
    let to_debt = available - to_buffer;

    if buffer_short > 0 {
        warnings.push(format!(
            "liquid is {buffer_short} minor units below the buffer, so that comes first — paying a card to zero and then meeting a repair puts the repair back on the card at its own rate WITH a fee, and the \"optimal\" payment has lost money"
        ));
    }
    for a in &position.accounts {
        if a.utilisation.is_some_and(|u| u >= opts.utilisation_concern) {
            warnings.push(format!(
                "{} is at {}% of its limit — bringing it under 30% may be worth more than the interest saved elsewhere, which is a judgement this does not make for you",
                a.institution,
                (a.utilisation.unwrap_or(0.0) * 100.0).round()
            ));
        }
    }
    for a in &debts {
        if promo_state_of(&a.account, &position.as_of, opts.promo_ends, opts.promo_urgency_days) == PromoState::Expiring {
            warnings.push(format!(
                "{}'s 0% rate ends {} — the whole balance starts accruing at once, which is why it is first rather than last",
                a.institution,
                promo_end_for(&a.account, opts.promo_ends).unwrap_or("")
            ));
        }
    }
    if !position.complete {
        warnings.push("the position under this is incomplete, so the surplus above is at best provisional".to_string());
    }

    let order = priority_order(&debts, opts.strategy, &position.as_of, opts.promo_ends, opts.promo_urgency_days);
    let head = order.first();

    let mut allocations: Vec<Allocation> = debts
        .iter()
        .map(|a| Allocation {
            kind: AllocationKind::Minimum,
            account: Some(a.account.clone()),
            label: format!("{} minimum", a.institution),
            amount: a.minimum_payment.unwrap_or_else(|| money(0, currency)),
            reason: "a missed minimum is a late fee, a penalty rate on the whole balance, and a credit event that outlasts the month".to_string(),
        })
        .collect();
    if to_buffer > 0 {
        allocations.push(Allocation {
            kind: AllocationKind::Buffer,
            account: None,
            label: "emergency buffer".to_string(),
            amount: money(to_buffer, currency),
            reason: "a buffer beats the rate until it exists — without one the next unplanned bill goes back onto the highest-rate card".to_string(),
        });
    }
    let target = match (to_debt > 0, head) {
        (true, Some(h)) => {
            let why = why_target(h, opts.strategy, &position.as_of, opts.promo_ends, opts.promo_urgency_days);
            allocations.push(Allocation {
                kind: AllocationKind::Extra,
                account: Some(h.account.clone()),
                label: format!("{} — above the minimum", h.institution),
                amount: money(to_debt, currency),
                reason: why.clone(),
            });
            Some(Target { account: h.account.clone(), institution: h.institution.clone(), why })
        }
        _ => None,
    };

    Priority {
        currency,
        strategy: opts.strategy,
        available: money(available, currency),
        lump_available: money(lump_available, currency),
        minimums: money(minimums, currency),
        to_buffer: money(to_buffer, currency),
        to_debt: money(to_debt, currency),
        allocations,
        target,
        order: order.iter().map(|a| a.account.clone()).collect(),
        warnings,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::account::Kind;
    use crate::money::usd;
    use crate::runway::{RunwayMonth, RunwayResult, Scenario};

    // SYNTHETIC FIXTURES ONLY.
    fn acct(account: &str, institution: &str, owed: Option<i64>, apr: Option<f64>, min: Option<i64>, util: Option<f64>) -> AccountPosition {
        AccountPosition {
            account: account.to_string(),
            institution: institution.to_string(),
            kind: Kind::Credit,
            balance: usd(-owed.unwrap_or(0)),
            as_of: "2026-06-30".to_string(),
            rolled_forward: 0,
            is_debt: true,
            owed: owed.map(usd),
            credit_limit: None,
            available: None,
            utilisation: util,
            apr,
            daily_interest: None,
            minimum_payment: min.map(usd),
        }
    }

    fn three() -> Vec<AccountPosition> {
        vec![
            acct("visa", "chase", Some(300_000), Some(0.2299), Some(6_000), None),
            acct("store", "storeco", Some(80_000), Some(0.0999), Some(2_500), None),
            acct("medical", "clinic", Some(150_000), Some(0.2999), Some(4_000), None),
        ]
    }

    fn pos(accounts: Vec<AccountPosition>, liquid: i64, complete: bool) -> Position {
        Position {
            as_of: "2026-06-30".to_string(),
            currency: Currency::USD,
            accounts,
            net_worth: usd(0),
            liquid: usd(liquid),
            total_debt: usd(0),
            daily_interest: usd(0),
            minimums_due: usd(0),
            weighted_apr: None,
            complete,
            provenance: "x".to_string(),
            problems: Vec::new(),
        }
    }

    fn rw(nets: &[i64], exhausts: Option<&str>) -> Runway {
        let months: Vec<RunwayMonth> = nets
            .iter()
            .enumerate()
            .map(|(i, n)| RunwayMonth {
                month: format!("2026-0{}", 7 + i),
                opening: usd(0),
                income: usd(0),
                obligations: usd(0),
                discretionary: usd(0),
                net: usd(*n),
                closing: usd(*n),
                shortfall: None,
            })
            .collect();
        let head = RunwayResult {
            scenario: Scenario::Low,
            months,
            exhausts_in: exhausts.map(str::to_string),
            months_of_cover: exhausts.map(|_| 0),
            tightest: None,
            monthly_gap: usd(0),
        };
        let empty = RunwayResult { scenario: Scenario::Expected, months: Vec::new(), exhausts_in: None, months_of_cover: None, tightest: None, monthly_gap: usd(0) };
        Runway {
            as_of: "2026-06-30".to_string(),
            currency: Currency::USD,
            starting_liquid: usd(0),
            low: head.clone(),
            expected: empty.clone(),
            high: empty,
            headline: head,
            through: None,
            problems: Vec::new(),
            provenance: "x".to_string(),
        }
    }

    #[test]
    fn the_surplus_is_the_worst_months_net_not_a_good_ones() {
        // Nets of 40000 / 45000 / 50000 give 40000, never 45000. A commitment made out of the best
        // month is a commitment that fails in the worst one.
        let p = prioritise(&pos(three(), 500_000, true), &rw(&[40_000, 45_000, 50_000], None), &PriorityOptions::new(usd(200_000)));
        assert_eq!(p.available.minor, 40_000);
        assert_eq!(p.minimums.minor, 12_500);
        assert_eq!(p.to_debt.minor, 40_000);
        assert_eq!(p.to_buffer.minor, 0, "liquid is already above the buffer");
        assert_eq!(p.lump_available.minor, 300_000, "a ONE-OFF, distinct from the monthly figure");
        assert_eq!(p.order, vec!["medical", "visa", "store"], "avalanche, by rate");
        assert_eq!(p.target.as_ref().expect("a target").account, "medical");
        assert!(p.target.as_ref().unwrap().why.contains("29.99%"));
        assert_eq!(total_commitment(&p).minor, 52_500);
        assert!(p.warnings.is_empty());
    }

    #[test]
    fn the_buffer_comes_before_the_rate_because_it_is_what_makes_the_rate_argument_true() {
        let p = prioritise(&pos(three(), 50_000, true), &rw(&[40_000, 45_000, 50_000], None), &PriorityOptions::new(usd(200_000)));
        assert_eq!(p.to_buffer.minor, 40_000, "the whole surplus goes to the buffer");
        assert_eq!(p.to_debt.minor, 0);
        assert!(p.target.is_none(), "nothing above the minimums, so there is no target this month");
        assert_eq!(p.lump_available.minor, 0);
        // Avalanche is optimal GIVEN the balance stays paid. Without a buffer that promise cannot be
        // made, and the warning says exactly why rather than just asserting a rule.
        assert!(p.warnings[0].contains("puts the repair back on the card at its own rate WITH a fee"));
        assert!(p.allocations.iter().any(|a| a.kind == AllocationKind::Buffer && a.account.is_none()));
    }

    #[test]
    fn a_runway_that_does_not_hold_means_there_is_no_surplus_at_all() {
        let p = prioritise(&pos(three(), 500_000, true), &rw(&[-5_000, 45_000, 50_000], Some("2026-07")), &PriorityOptions::new(usd(200_000)));
        // The honest and unusual answer: pay the minimums and nothing more.
        assert_eq!(p.available.minor, 0);
        assert_eq!(p.to_debt.minor, 0);
        assert_eq!(p.to_buffer.minor, 0);
        assert!(p.target.is_none());
        assert_eq!(total_commitment(&p).minor, 12_500, "exactly the minimums");
        assert!(p.warnings[0].contains("brings that date forward"));
        // The minimums are STILL allocated — they are not negotiable regardless.
        assert_eq!(p.allocations.iter().filter(|a| a.kind == AllocationKind::Minimum).count(), 3);
    }

    #[test]
    fn a_live_promotion_goes_last_because_a_dollar_there_buys_nothing() {
        let ends = [("medical".to_string(), "2027-06-01".to_string())];
        let opts = PriorityOptions { promo_ends: &ends, ..PriorityOptions::new(usd(0)) };
        let p = prioritise(&pos(three(), 500_000, true), &rw(&[40_000], None), &opts);
        // medical carries the HIGHEST rate and is still last — while the promotion runs it costs
        // nothing to carry, so paying it is the worst use of a dollar.
        assert_eq!(p.order, vec!["visa", "store", "medical"]);
        assert_eq!(p.target.as_ref().expect("a target").account, "visa");
        assert!(p.warnings.is_empty(), "a live promotion is not a problem, it is an advantage");
    }

    #[test]
    fn an_expiring_promotion_jumps_to_the_front_on_a_date() {
        let ends = [("store".to_string(), "2026-08-01".to_string())];
        let opts = PriorityOptions { promo_ends: &ends, ..PriorityOptions::new(usd(0)) };
        let p = prioritise(&pos(three(), 500_000, true), &rw(&[40_000], None), &opts);
        // store has the LOWEST rate and the smallest balance, and is first anyway.
        assert_eq!(p.order, vec!["store", "medical", "visa"]);
        assert_eq!(p.target.as_ref().expect("a target").account, "store");
        assert!(p.target.as_ref().unwrap().why.contains("ends 2026-08-01 and the whole balance begins accruing at once"));
        assert!(p.warnings[0].contains("which is why it is first rather than last"));
    }

    #[test]
    fn the_same_promotion_inverts_on_nothing_but_the_date() {
        let ends = [("store".to_string(), "2026-08-01".to_string())];
        let far = [("store".to_string(), "2027-08-01".to_string())];
        let as_of = "2026-06-30";
        // 32 days out at a 90-day urgency: EXPIRING. A year out: LIVE. Same balance, same rate.
        assert_eq!(promo_state_of("store", as_of, &ends, 90), PromoState::Expiring);
        assert_eq!(promo_state_of("store", as_of, &far, 90), PromoState::Live);
        // Tighten the urgency window and the same date reads as merely live.
        assert_eq!(promo_state_of("store", as_of, &ends, 7), PromoState::Live);
        // A date already passed is not a promotion at all — otherwise it would stay pinned to the
        // front of the list forever.
        let past = [("store".to_string(), "2026-01-01".to_string())];
        assert_eq!(promo_state_of("store", as_of, &past, 90), PromoState::None);
        assert_eq!(promo_state_of("nothing-here", as_of, &ends, 90), PromoState::None);
    }

    #[test]
    fn among_expiring_promotions_the_biggest_exposure_goes_first() {
        // Not the rate — the rate is zero for both. What matters is how much is about to start
        // accruing at once.
        let debts = vec![acct("a", "a", Some(10_000), Some(0.3), Some(100), None), acct("b", "b", Some(90_000), Some(0.1), Some(100), None)];
        let ends = [("a".to_string(), "2026-08-01".to_string()), ("b".to_string(), "2026-08-01".to_string())];
        let order = priority_order(&debts, Strategy::Avalanche, "2026-06-30", &ends, 90);
        assert_eq!(order.iter().map(|a| a.account.clone()).collect::<Vec<_>>(), vec!["b", "a"]);
    }

    #[test]
    fn snowball_changes_the_target_and_the_reason_given_for_it() {
        let opts = PriorityOptions { strategy: Strategy::Snowball, ..PriorityOptions::new(usd(0)) };
        let p = prioritise(&pos(three(), 500_000, true), &rw(&[40_000], None), &opts);
        assert_eq!(p.order, vec!["store", "medical", "visa"]);
        assert!(p.target.as_ref().unwrap().why.contains("clears soonest and its minimum rolls into the next one"));
    }

    #[test]
    fn no_runway_at_all_recommends_nothing_above_the_minimums() {
        let p = prioritise(&pos(three(), 500_000, true), &rw(&[], None), &PriorityOptions::new(usd(0)));
        assert_eq!(p.available.minor, 0);
        assert!(p.target.is_none());
        assert!(p.warnings[0].contains("no runway to read a surplus from"));
        // The ORDER is still computed, so the answer after this one is visible once there is money.
        assert_eq!(p.order, vec!["medical", "visa", "store"]);
    }

    #[test]
    fn a_maxed_line_is_called_out_without_the_judgement_being_made_for_you() {
        let p = prioritise(&pos(vec![acct("visa", "chase", Some(300_000), Some(0.2299), Some(6_000), Some(0.95))], 500_000, true), &rw(&[40_000], None), &PriorityOptions::new(usd(0)));
        assert!(p.warnings[0].contains("at 95% of its limit"));
        assert!(p.warnings[0].contains("which is a judgement this does not make for you"));
    }

    #[test]
    fn a_debt_with_no_known_rate_is_named_as_the_likely_expensive_one() {
        let p = prioritise(&pos(vec![acct("mystery", "unknownbank", Some(300_000), None, Some(6_000), None)], 500_000, true), &rw(&[40_000], None), &PriorityOptions::new(usd(0)));
        assert!(p.target.as_ref().unwrap().why.contains("no known rate, which is the one most likely to be the expensive one"));
    }

    #[test]
    fn an_incomplete_position_makes_the_surplus_provisional_and_says_so() {
        let p = prioritise(&pos(three(), 500_000, false), &rw(&[40_000], None), &PriorityOptions::new(usd(0)));
        assert!(p.warnings.iter().any(|w| w.contains("at best provisional")));
        assert_eq!(p.available.minor, 40_000, "it is still computed — provisional is not absent");
    }
}
